const ruta = n8nApi.rutaUnica("vyv-ver");
const nodos = (v) => [n8nApi.nodoWebhook("GET", ruta), n8nApi.nodoCampos({ v })];
n8nApi.crearWorkflowActivo("VyV versi\xF3n publicada", nodos(1), n8nApi.cadena("Webhook", "Edit Fields")).then((publicado) => {
  wf = publicado;
  n8nApi.llamarWebhook("GET", ruta).its("body").should("deep.eq", { v: 1 });
  cy.visitarN8n(`/workflow/${wf.id}`);
  cy.get(indicador, { timeout: 3e4 }).should("have.attr", "class").and("match", /indicatorPublished/);
  n8nApi.req("PATCH", `/rest/workflows/${wf.id}`, { versionId: wf.versionId, nodes: nodos(2), connections: wf.connections }).then(n8nApi.ok).then((guardado) => {
    n8nApi.llamarWebhook("GET", ruta).then((r) => {
      cy.evidencia(`Tras guardar v=2 sin publicar, producci\xF3n responde ${JSON.stringify(r.body)}`);
      expect(r.body, "producci\xF3n sigue en la versi\xF3n publicada").to.deep.eq({ v: 1 });
    });
    cy.reload();
    cy.get(indicador, { timeout: 3e4 }).should("have.attr", "class").and("match", /indicatorChanges/);
    cy.screenshot("CP-WF-03-07_cambios-sin-publicar");
    n8nApi.req("POST", `/rest/workflows/${wf.id}/activate`, { versionId: guardado.versionId }).its("status").should("eq", 200);
    const hastaV2 = (restantes = 20) => n8nApi.llamarWebhook("GET", ruta).then((r) => r.body?.v === 2 || restantes <= 1 ? r : cy.wait(500).then(() => hastaV2(restantes - 1)));
    hastaV2().then((r) => {
      cy.evidencia(`Tras publicar, producci\xF3n responde ${JSON.stringify(r.body)}`);
      expect(r.body).to.deep.eq({ v: 2 });
    });
    cy.reload();
    cy.get(indicador, { timeout: 3e4 }).should("have.attr", "class").and("match", /indicatorPublished/);
  });
});

publicar("VyV 60 ejecuciones").then(({ wf, ruta }) => {
  n8nApi.llamarWebhook("GET", ruta).its("status").should("eq", 200);
  Cypress._.times(59, () => cy.request({ url: `/webhook/${ruta}`, log: false }));
  n8nApi.esperarEjecuciones(wf.id, 60).should("have.length", 60);
  todasLasPaginas(wf.id).then((ids) => {
    cy.evidencia(`API en p\xE1ginas de 20: ${ids.length} IDs, ${new Set(ids).size} distintos`);
    expect(ids).to.have.length(60);
    expect(new Set(ids).size, "sin repetidos").to.eq(60);
  });
  cy.visitarN8n(`/workflow/${wf.id}/executions`);
  cy.get(tarjetas, { timeout: 3e4 }).should("have.length.at.least", 10);
  const desplazar = (restantes = 15) => cy.get(tarjetas).then(($t) => {
    if ($t.length >= 60 || restantes <= 0) return;
    cy.get('[data-test-id="current-executions-list"]').scrollTo("bottom", { ensureScrollable: false });
    cy.wait(700).then(() => desplazar(restantes - 1));
  });
  desplazar();
  cy.get(tarjetas).should("have.length", 60).then(($t) => {
    const enPantalla = [...$t].map((el) => el.querySelector("a")?.getAttribute("href") ?? el.textContent);
    cy.evidencia(`Lista del workflow tras desplazarse: ${$t.length} tarjetas, ${new Set(enPantalla).size} distintas`);
    expect(new Set(enPantalla).size).to.eq(60);
  });
  cy.screenshot("CP-EX-01-05_lista-completa");
});

