const nodos = [disparador, n8nApi.nodoEspera(20, "seconds", "Wait", [220, 0]), n8nApi.nodoCampos({ fin: true }, "Edit Fields", [440, 0])];
crear("VyV detener manual", nodos, n8nApi.cadena("Manual Trigger", "Wait", "Edit Fields")).then((wf) => {
  cy.visitarN8n(`/workflow/${wf.id}`);
  cy.get('[data-test-id="execute-workflow-button"]', { timeout: 3e4 }).click();
  cy.get('[data-test-id="stop-execution-button"]', { timeout: 3e4 }).should("be.visible");
  cy.wait(3e3);
  cy.get('[data-test-id="stop-execution-button"]').click();
  cy.get('[data-test-id="stop-execution-button"]', { timeout: 3e4 }).should("not.exist");
  cy.screenshot("CP-EX-04-01_detenida");
  n8nApi.esperarEjecuciones(wf.id, 1, (e) => !["new", "running", "waiting"].includes(e.status)).then(
    ([e]) => n8nApi.detalleEjecucion(e.id).then((d) => {
      const nodos2 = Object.keys(d.data.resultData.runData);
      cy.evidencia(`Ejecuci\xF3n ${e.id}: ${e.mode}/${e.status} \xB7 nodos ejecutados: ${nodos2.join(", ")}`);
      expect(e).to.include({ mode: "manual", status: "canceled" });
      expect(nodos2, "Edit Fields no se ejecuta").not.to.include("Edit Fields");
    })
  );
});

